import pathlib, click
from click.testing import CliRunner

# Option / argument: value handed to the callback is the exact path type.
@click.command()
@click.option("--p", type=click.Path(path_type=pathlib.Path))
@click.argument("q", type=click.Path(path_type=pathlib.Path))
def cli(p, q):
    click.echo(f"{type(p).__module__}.{type(p).__name__} {type(q).__name__}")

r = CliRunner().invoke(cli, ["--p", "a.txt", "b.txt"], catch_exceptions=False)
print("option+argument:", r.output.strip())

# Prompt path uses the same converter.
@click.command()
def ask():
    v = click.prompt("File", type=click.Path(path_type=pathlib.Path), default="x.txt")
    click.echo(f"prompt -> {type(v).__name__}")

r = CliRunner().invoke(ask, [], input="c.txt\n", catch_exceptions=False)
print(r.output.strip())
