import pathlib, click, ast, inspect
src = inspect.getsource(click.Path)
tree = ast.parse(textwrap_dedent := "\n".join(l[4:] if l.startswith("    ") else l for l in src.splitlines()))
n = 0
for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.name == "__init__":
        n += 1
        decs = [ast.unparse(d) for d in node.decorator_list]
        print(f"__init__ #{n} decorators={decs}")
        print("   self      =", ast.unparse(node.args.args[0].annotation))
        kw = {a.arg: a for a in node.args.kwonlyargs}
        pos = {a.arg: a for a in node.args.args}
        pt = pos.get("path_type")
        if pt is None:
            pt = kw.get("path_type")
        if pt is not None:
            print("   path_type =", ast.unparse(pt.annotation), "default=", ast.unparse(pt) if pt is not None else None)
